function relationMatch(e){const r=$('#relation').value;if(r==='all')return true;if(r==='personal')return !['Shared milestone','Connected ideas','Context','Background'].includes(e[2]);if(r==='Rivalry')return ['Rivalry','Debate'].includes(e[2]);if(r==='Evidence')return ['Evidence','Tested'].includes(e[2]);if(r==='ideas')return !['Mentorship','Collaboration','Rivalry','Debate','Evidence','Tested'].includes(e[2]);return e[2]===r}
function eraMatch(n){const ranges={ancient:[-Infinity,499],medieval:[500,1499],early:[1500,1799],nineteenth:[1800,1899],modern:[1900,1949],late:[1950,1999],current:[2000,Infinity]},r=ranges[$('#era').value];return !r||(n.year>=r[0]&&n.year<=r[1])}
function filtered(){const q=norm($('#search').value.trim()),f=$('#field').value;const connected=new Set(edges().filter(relationMatch).flatMap(e=>e.slice(0,2)));return nodes().filter(n=>(f==='All'||n.field===f||n.fields?.includes(f))&&eraMatch(n)&&($('#relation').value==='all'||connected.has(n.id))&&(!q||norm([n.title,n.text,n.field,n.location,...(n.people||[]).map(id=>pMap.get(id)?.title),...(n.contributions||[]).map(id=>dMap.get(id)?.title)].join(' ')).includes(q))).sort((a,b)=>a.year-b.year||a.title.localeCompare(b.title))}
function clearFilters(){for(const [id,v] of [['search',''],['field','All'],['era','all'],['relation','all']])$('#'+id).value=v;limit=24}
function selectNode(id,newMode=mode,keepJourney=false){mode=newMode;selected=id;if(!keepJourney)journey=null;render();history.replaceState(null,'',`#node=${mode==='people'?'p':'d'}/${encodeURIComponent(id)}`)}
