function mediaImage(key,cls='',lazy=true){const a=visualAssets[key];return a?`<img class="${esc(cls)}" src="${esc(a.src)}" alt="${esc(a.alt)}" width="${a.width}" height="${a.height}" loading="${lazy?'lazy':'eager'}" decoding="async">`:''}
function imageCredit(key){const a=visualAssets[key];return `<details class="image-credit"><summary>Image credit & source</summary><span>${esc(a.credit)} <a href="${esc(a.source)}" target="_blank" rel="noopener">Image source</a> · <a href="${esc(a.licenseUrl)}" target="_blank" rel="noopener">${esc(a.license)}</a></span></details>`}
function mediaFigure(key,cls=''){const a=visualAssets[key];return a?`<figure class="archive-figure ${esc(cls)}"><a class="image-original" href="${esc(a.src)}" target="_blank" rel="noopener" aria-label="Open full image: ${esc(a.alt)}">${mediaImage(key)}</a><figcaption>${esc(a.caption)}${imageCredit(key)}</figcaption></figure>`:''}
function storyCover(s){const v=storyVisuals[s.id];return v?`<div class="story-cover ${v.hero?'story-cover-scene':''}">${v.hero?`<div>${mediaImage(v.hero)}</div>`:''}${(v.portraits||[]).map(p=>`<div>${mediaImage(p.key,'',true)}<span>${esc(p.name)}</span></div>`).join('')}<small>AN ILLUSTRATED HISTORY</small></div>`:''}
function storyPortraits(s){const v=storyVisuals[s.id];return v?`${v.hero?mediaFigure(v.hero,'story-lead-image'):''}<div class="story-portrait-pair ${(v.portraits||[]).length===1?'single-portrait':''}" ${v.portraits?'':'hidden'}>${(v.portraits||[]).map(p=>`<figure><div class="portrait-mat">${mediaImage(p.key,'',false)}</div><figcaption><small>${esc(p.role)}</small><strong>${esc(p.name)}</strong><p>${esc(visualAssets[p.key].caption)}</p>${imageCredit(p.key)}</figcaption></figure>`).join('')}</div>`:''}
